  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(27, 54, 93, 0.08);
  background: rgba(255, 255, 255, 0.6);
}

.ub-find-board__preview-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
  background: rgba(27, 54, 93, 0.06);
}

.ub-find-board__preview-titles {
  flex: 1 1 auto;
  min-width: 0;
}

.ub-find-board__preview-name {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: #374151;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ub-find-board__preview-owner {
  margin: 2px 0 0;
  font-size: 14px;
  font-weight: 500;
  color: rgba(27, 54, 93, 0.55);
  line-height: 1.2;
}

.ub-find-board__preview-grid-size {
  font-size: 12px;
  color: rgba(27, 54, 93, 0.6);
  font-weight: 600;
}

.ub-find-board__preview-open {
  flex-shrink: 0;
}

.ub-find-board__preview-grid-wrap {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 12px;
  position: relative;
}

/* Empty / loading / error states */
.ub-find-board__preview-empty,
.ub-find-board__preview-state {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  color: rgba(27, 54, 93, 0.6);
}

/* Loading / error states: vertically centred, but pulled to the RIGHT edge of the
   preview so the "Loading board…" message sits just left of the board that was
   clicked in the panel, rather than lost in the middle of the empty pane. */
.ub-find-board__preview-state {
  justify-content: center;
  align-items: flex-start;
  gap: 10px;
  text-align: left;
  padding: 32px 40px;
}

/* Empty state: TOP-aligned in the pane, message inside an outlined card. */
.ub-find-board__preview-empty {
  justify-content: flex-start;
  padding: 28px 24px;
}

.ub-find-board__preview-empty-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
  padding: 30px 34px;
  max-width: 440px;
  width: 100%;
  border: 1px solid rgba(27, 54, 93, 0.14);
  border-radius: 16px;
  /* Double-outline effect: the border is the inner line; an offset outline draws a
     second, lighter line just outside it with a small gap between. */
  outline: 2px solid rgba(27, 54, 93, 0.1);
  outline-offset: 5px;
  background: transparent; /* no fill — the empty state should read as empty */
}

.ub-find-board__preview-empty-icon {
  color: rgba(27, 54, 93, 0.28);
  margin-bottom: 4px;
}

.ub-find-board__preview-empty-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: rgba(27, 54, 93, 0.75);
}

.ub-find-board__preview-empty-sub {
  margin: 0;
  font-size: 14px;
  color: rgba(27, 54, 93, 0.55);
  max-width: 320px;
}

/* ── Right: collection-style board panel ── */
.ub-find-board__panel {
  min-height: 0;
  border-radius: 14px;
  background: #fff;
  border: 1px solid rgba(27, 54, 93, 0.08);
  box-shadow: 0 4px 16px rgba(27, 54, 93, 0.08);
  overflow: hidden;
}

.ub-find-board__panel .md-board-collection__header {
  padding: 14px 14px 10px;
}

.ub-find-board__panel .md-board-collection__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
}

.ub-find-board__create {
  width: 100%;
  margin-top: 10px;
  justify-content: center;
}

/* Primary action buttons (Create a New Board, Open Board): keep the shared
   .md-btn--primary.md-btn--pill look untouched (the original lighter wash, text,
   and blur all inherit from the base) — only swap the base's light hairline for
   a small dark outline so the buttons read with a bit more definition against
   the pale panel.
   SPECIFICITY: the base rule is (0,2,0) with !important; !important vs
   !important is decided by specificity, so this override MUST include both
   button classes to win. The :hover/:focus-visible selectors are listed too
   ((0,4,0)) so the base :hover ((0,3,0), which resets border-color) can't drop
   the dark outline on hover. */
.ub-find-board__create.md-btn--primary.md-btn--pill,
.ub-find-board__preview-open.md-btn--primary.md-btn--pill,
.ub-find-board__create.md-btn--primary.md-btn--pill:hover,
.ub-find-board__preview-open.md-btn--primary.md-btn--pill:hover,
.ub-find-board__create.md-btn--primary.md-btn--pill:focus-visible,
.ub-find-board__preview-open.md-btn--primary.md-btn--pill:focus-visible {
  border: 1px solid rgba(27, 54, 93, 0.4) !important;
}

/* Selected row highlight (mirrors the collection hover tint) */
.md-board-collection__item--selected {
  background: rgba(27, 54, 93, 0.1);
  color: #1B365D;
}

/* ≤900px: stack the two panes (panel first, preview below) */
@media (max-width: 900px) {
  .ub-find-board {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(320px, 1fr);
  }
}
/* ==============================================================
   BOARD PICKER — page chrome + compact board rows
   ==============================================================
   Owns everything the standalone home-board picker adds on top of the shared
   `md-home-boards-picker__*` layout that also serves setup and /search/home.
   Kept in its own partial (rather than appended to app.scss) so the compact and
   detailed views stay separable and neither becomes a pile of overrides.

   Two naming families live here on purpose:
     bp-*                              NEW page chrome — heading, toolbar,
                                       search, segmented control. Nothing else
                                       in the app uses these names.
     .ll-boards-grid--compact …        COMPACT-ONLY modifiers on the existing
                                       card markup. Every one is scoped inside
                                       that modifier, so the detailed view keeps
                                       its current appearance untouched.
                                       SHARED, not picker-only (2026-08-16): the
                                       Boards page reuses the identical compact
                                       rows, so these rules key off the neutral
                                       `.ll-boards-grid--compact` modifier and the
                                       `.simple_board_holder` wrapper that BOTH
                                       pages already put around <BoardIcon>,
                                       rather than the picker's own class names.

   Palette comes from _variables.scss ($la-navy #1B365D, $brand-verdigris
   #2A9D8F, $brand-verdigris-aa #1A7B7A, $brand-dusty-denim-aa #2860C9,
   $brand-charcoal-dark #374151). Verdigris is used for borders, dots and fills
   only — never for body text on white, where the AA-dark variants are used.
   ============================================================== */
/* Minimum interactive target. AAC users include people with significant motor
   differences — this floor is not negotiable at any breakpoint. */
/* --------------------------------------------------------------
   0. Shell background stability
   --------------------------------------------------------------
   The page background visibly CHANGED when switching Compact <-> Detailed. It is not a
   toggle bug: the background declaration is byte-identical in both states (verified —
   same image, size and colour). `.md-shell`'s mesh is six radial-gradients positioned in
   PERCENTAGES, and the shell's height is content-driven — measured 1269px in compact vs
   2550px in detailed. Percentage positions resolve against the painting area, so the
   whole mesh re-positions and re-stretches when the list gets shorter.
   `background-attachment: fixed` resolves that area against the VIEWPORT instead, so the
   mesh is identical regardless of how tall the content is.
   SCOPED TO THIS PAGE: fixed attachment is known to be expensive to repaint while
   scrolling on some mobile browsers, so it is not applied app-wide — only here, where a
   control flips the content height dramatically in place.

   `!important` IS REQUIRED here, not decoration: `.md-shell`'s background is declared as
   an `!important` SHORTHAND (app.scss ~44170), and a shorthand resets every sub-property
   — so it sets `background-attachment: scroll !important` and silently outranked a plain
   longhand. Verified: without it the computed value stayed `scroll`.

   SPECIFICITY IS ALSO REQUIRED: this partial is `@use`d, so it emits BEFORE app.scss. At
   equal specificity (0,1,0) with both sides `!important`, source order decided and
   app.scss still won — verified, the computed value stayed `scroll` even with the flag.
   `.md-shell.md-shell--board-picker` is (0,2,0) and wins outright. */
.md-shell.md-shell--board-picker {
  background-attachment: fixed !important;
}

/* --------------------------------------------------------------
   1. Page heading
   -------------------------------------------------------------- */
/* Left-aligned, not centred: everything below it — the category rail, the
   results panel, the board rows — starts on the same left edge, and a centred
   title made the top of the page read as a separate introductory band.
   A ROW, not a block: the supervisor flow puts an "OR / Create My Own Board"
   aside opposite the heading (see .bp-page-head__aside). With no aside — the
   self flow — a single flex child lays out exactly as the block did. */
.md-shell--board-picker .bp-page-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px 24px;
  padding: 0;
  margin: 0;
  text-align: left;
}

/* Heading column. The 340px basis is the wrap trigger: narrower than that and
   the aside drops to its own row rather than squeezing the title. */
.md-shell--board-picker .bp-page-head__text {
  flex: 1 1 340px;
  min-width: 0;
}

.md-shell--board-picker .bp-page-head__aside {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Way back to the entry overlay (.bp-options), which owns the quick-assign and
   create-a-board shortcuts. Deliberately a LINK, not one of the page's pills:
   the shortcuts themselves live in the overlay, and a second pill up here read
   as a third competing action. A <button> underneath — it reopens an overlay,
   it does not navigate — so the button chrome is stripped back to link
   appearance while the 44px target floor is kept. */
.md-shell--board-picker .bp-page-head__options-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: #1A7B7A;
  font-size: 15px;
  font-weight: 650;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.md-shell--board-picker .bp-page-head__options-link:hover {
  color: #1B365D;
}

.md-shell--board-picker .bp-page-head__options-link:focus-visible {
  outline: 3px solid #1B365D !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 4px rgba(27, 54, 93, 0.15) !important;
}
@media (forced-colors: active) {
  .md-shell--board-picker .bp-page-head__options-link:focus-visible {
    outline-color: Highlight !important;
    box-shadow: none !important;
  }
}

/* Only the box fixes live here. Size / weight / colour / alignment are set in
   app.scss on `.md-shell--board-picker .md-card--board-picker .md-hero--home-boards
   .md-hero__title` (~5220) — that rule carries `!important` to beat the global
   `.md-hero__title`, so any type declaration here would be dead weight.
   `display` and `height` undo the legacy `h1 { display: inline-block;
   height: 60px }` (app.scss ~1826, written for the old nav-header logo row).
   Nothing else on this page sets an h1 height, so that bare element rule was
   winning: it pinned the heading box to 60px with the text at the top, and the
   ~37px of dead space below it read as a gap before the subtitle. The
   title→subtitle gap is the SUBTITLE's margin-top — the global
   `.md-hero__title { margin: 0 !important }` (~44534) kills any margin here. */
.md-shell--board-picker .bp-page-head__title {
  display: block;
  height: auto;
  margin: 0;
  letter-spacing: -0.01em;
}

.md-shell--board-picker .bp-page-head__subtitle {
  /* Owns the title→subtitle gap (the h1's own margin is pinned to 0 by a global
     !important — see .bp-page-head__title above). This element carries only the
     bp-* class, so nothing competes for its margin. */
  margin: 8px 0 0;
  font-size: 16px;
  line-height: 1.45;
  color: #374151;
}

/* --------------------------------------------------------------
   2. Supervisor entry overlay (.bp-options)
   Shown to a supporter opening the picker for a communicator, before they
   engage with the grid: browse, quick-assign, or create.

   RELATIONSHIP TO .nb-create-chooser (app.scss ~54560): same SHAPE on purpose —
   scrim, one panel, title, hairline separator, stacked options with OR between
   them — because it is the same kind of decision. Everything that carries
   identity is different on purpose, so a supporter never mistakes this for the
   create-board chooser:
     scrim    verdigris -> navy, not navy -> navy
     panel    wider (520), accent bar across the top, LEFT-aligned copy
     eyebrow  a task chip ("Home board setup") the chooser does not have
     options  left-aligned with a fixed icon well; the chooser centres its pairs
   -------------------------------------------------------------- */
.bp-options {
  position: fixed;
  inset: 0;
  /* BELOW Bootstrap's modal layer (.modal-backdrop 1040 / .modal 1050), not
     above it. This scrim was 5900 — chosen only against the create-board
     chooser's 6000 — which put it over every dialog its own buttons can open:
       • "Create New Board" runs appState.check_for_needing_purchase(), whose
         promise settles ONLY when the user dismisses the premium-required
         modal. Painted behind the scrim it was invisible and unclickable, so
         for an expired or modeling-only supporter the flow hung with no way
         out but a page reload.
       • Quick Assign's failure paths call modal.error(...) — the message
         landed under the scrim, so the button just re-enabled in silence.
     1030 keeps it over the page and its chrome (navbar ~1000-1001) while both
     the backdrop and the dialog clear it. Still below the create-board
     chooser's 6000, so that ordering is unchanged. */
  z-index: 1030;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  overflow-y: auto;
  background: radial-gradient(120% 90% at 50% 38%, rgba(26, 123, 122, 0.55), rgba(27, 54, 93, 0.82));
  backdrop-filter: blur(7px) saturate(0.92);
  -webkit-backdrop-filter: blur(7px) saturate(0.92);
}

.bp-options__panel {
  position: relative;
  width: 100%;
  max-width: 520px;
  padding: 24px 32px 32px;
  border-radius: 20px;
  overflow: hidden; /* clips the accent bar to the rounded corner */
  background: #fff;
  border: 1px solid rgba(27, 54, 93, 0.1);
  box-shadow: 0 24px 60px rgba(27, 54, 93, 0.3), 0 4px 12px rgba(27, 54, 93, 0.14);
  text-align: left;
}

/* Accent bar — the fastest read that this is not the create-board chooser. */
.bp-options__panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: linear-gradient(90deg, #1A7B7A 0%, rgba(40, 96, 201, 0.85) 100%);
}

.bp-options__close {
  position: absolute;
  top: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(27, 54, 93, 0.1);
  background: rgba(27, 54, 93, 0.04);
  color: rgba(27, 54, 93, 0.55);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.bp-options__close:hover {
  background: rgba(27, 54, 93, 0.09);
  color: #1B365D;
}

.bp-options__close:focus-visible {
  outline: 3px solid #1B365D !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 4px rgba(27, 54, 93, 0.15) !important;
}
@media (forced-colors: active) {
  .bp-options__close:focus-visible {
    outline-color: Highlight !important;
    box-shadow: none !important;
  }
}

.bp-options__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 12px;
  padding: 5px 12px;
  border-radius: 999px;
  background: rgba(42, 157, 143, 0.12);
  color: #1A7B7A;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.bp-options__title {
  margin: 0;
  font-size: 22px;
  font-weight: 750;
  line-height: 1.25;
  letter-spacing: -0.01em;
  color: #1B365D;
}

.bp-options__subtitle {
  margin: 8px 0 0;
  font-size: 15px;
  line-height: 1.45;
  color: #374151;
}

/* The app's modern divider: verdigris→navy hairline fading at both ends. Same
   recipe as .nb-create-chooser__separator, left-anchored rather than centred to
   match this panel's alignment. */
.bp-options__separator {
  height: 2px;
  margin: 16px 0 24px;
  border-radius: 2px;
  background: linear-gradient(90deg, rgba(26, 123, 122, 0.55) 0%, rgba(27, 54, 93, 0.32) 45%, rgba(27, 54, 93, 0) 100%);
}

.bp-options__list {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
}

.bp-options__btn {
  display: flex;
  align-items: center;
  /* The icon + label travel together as one CENTRED group, the same way the
     create-board chooser sets its options — the row is the target, so the label
     reads as the middle of it rather than as a list item hanging off a rail. */
  justify-content: center;
  gap: 16px;
  width: 100%;
  min-height: 68px;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid rgba(27, 54, 93, 0.14);
  background: linear-gradient(180deg, #ffffff 0%, #f4f7fb 100%);
  color: #1B365D;
  font-size: 17px;
  font-weight: 650;
  text-align: center;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(27, 54, 93, 0.06);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.bp-options__btn:hover:not([disabled]) {
  border-color: rgba(26, 123, 122, 0.45);
  box-shadow: 0 8px 20px rgba(27, 54, 93, 0.1);
  transform: translateY(-1px);
}

.bp-options__btn:focus-visible {
  outline: 3px solid #1B365D !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 4px rgba(27, 54, 93, 0.15) !important;
}
@media (forced-colors: active) {
  .bp-options__btn:focus-visible {
    outline-color: Highlight !important;
    box-shadow: none !important;
  }
}

.bp-options__btn[disabled] {
  opacity: 0.6;
  cursor: default;
  box-shadow: none;
}

/* Fixed well so the three glyphs read as one set however wide each path is. */
.bp-options__btn-icon {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(42, 157, 143, 0.1);
  color: #1A7B7A;
}

.bp-options__btn-label {
  min-width: 0;
}

/* Quick assign is the shortcut, not the default — a warmer well marks it as the
   different KIND of action without promoting it above browsing. */
.bp-options__btn--quick .bp-options__btn-icon {
  background: rgba(76, 134, 216, 0.14);
  color: #2860C9;
}

/* In-flight ellipsis: three dots fading in sequence. A copy of a full board set
   runs for minutes, and a static "…" makes a working page look hung. */
.bp-options__dots {
  display: inline-flex;
  align-items: flex-end;
  gap: 3px;
  margin-left: 4px;
  /* Reserve the full width up front so the label doesn't jitter as dots fade. */
  min-width: 21px;
}

.bp-options__dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.25;
  animation: bp-options-dot 1.2s ease-in-out infinite;
}

.bp-options__dot:nth-child(2) {
  animation-delay: 0.2s;
}

.bp-options__dot:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes bp-options-dot {
  0%, 70%, 100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  35% {
    opacity: 1;
    transform: translateY(-2px);
  }
}
/* What the wait is FOR. 14px keeps it clearly secondary to the 17px option
   labels while staying readable. */
.bp-options__progress-note {
  margin: 8px 0 0;
  padding: 0 4px;
  font-size: 14px;
  line-height: 1.45;
  color: #374151;
  text-align: center;
}

.bp-options__or {
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(27, 54, 93, 0.45);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.bp-options__or::before,
.bp-options__or::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: rgba(27, 54, 93, 0.12);
}

/* --------------------------------------------------------------
   3. Results panel head + toolbar
   The panel reads top to bottom as: WHICH boards (head) -> what they are
   (description) -> controls (toolbar) -> the boards. The head and the toolbar
   were one row until this pass, which put the controls above the description
   and gave the panel a second introduction.
   -------------------------------------------------------------- */
/* Title and count on one baseline-aligned row, separated by a middot. */
.bp-results-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
  margin: 0 0 7px;
}

.bp-results-head__title {
  margin: 0;
  font-size: 20px;
  font-weight: 650;
  line-height: 1.25;
  color: #1B365D;
}

.bp-results-head__sep {
  /* Big and solid enough to actually read as a separator — at 16px/0.30 the
     middot was nearly invisible against the panel. `line-height: 1` keeps the
     taller glyph from growing the baseline-aligned row. */
  color: rgba(27, 54, 93, 0.55);
  font-size: 24px;
  line-height: 1;
}

.bp-results-head__count {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  color: #374151;
}

/* Controls only. Shares the board grid's left edge; the search field goes
   full-width once the row wraps rather than shrinking below the touch floor. */
.bp-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 16px;
  margin: 0 0 15px;
}

.bp-toolbar__controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  /* Grow to fill the toolbar line so the two controls can sit at opposite ends.
     Without this the block is content-sized, and once the toolbar wraps it is
     the only item on its line — where the parent's `space-between` parks it
     left with all the slack stranded to its right. `space-between` here (rather
     than an auto margin on the switcher) keeps ONE alignment mechanism, and it
     is what puts search first / switcher second on every line. */
  flex: 1 1 auto;
  min-width: 0;
}

/* --------------------------------------------------------------
   4. Search
   -------------------------------------------------------------- */
.bp-search {
  position: relative;
  display: flex;
  align-items: center;
  /* Grows with the toolbar up to a readable ceiling — past ~450px a search
     field is mostly empty space. */
  width: min(100%, 450px);
  flex: 1 1 280px;
}

.bp-search__icon {
  position: absolute;
  left: 14px;
  display: inline-flex;
  color: rgba(27, 54, 93, 0.55);
  pointer-events: none;
}

.bp-search__input {
  width: 100%;
  /* 46px: matches the segmented control beside it (44px segments + its 1px
     borders), so the two read as one toolbar row. */
  height: 46px;
  padding: 0 40px 0 42px;
  /* A visible edge, not a hairline — this is an input, and it has to look like
     one against the panel behind it. */
  border: 1px solid rgba(27, 54, 93, 0.18);
  border-radius: 12px;
  background: #FFFFFF;
  color: #1B365D;
