  gap: 24px;
  padding: 106px 28px 24px !important;
}

body.ll-view-basic .md-shell--org-directory > .md-workspace,
body.ll-view-basic .md-shell--board-picker > .md-workspace,
body.ll-view-basic .la-system-settings .la-main > .md-workspace {
