.ch-comm {
  position: relative;
  overflow: visible;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.42) 48%, rgba(255, 255, 255, 0) 64%), linear-gradient(160deg, #EAEFF6 0%, #D2DAE5 100%);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.95), inset 0 -2px 4px rgba(15, 23, 42, 0.1), 0 3px 8px rgba(27, 54, 93, 0.18);
}

.ch-comm--highlighted {
  outline: 3px solid #1A7B7A;
  outline-offset: 2px;
}

.ch-comm__head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ch-comm__avatar {
  flex: 0 0 auto;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  background: #fff;
  border: 1px solid rgba(17, 26, 46, 0.42);
  box-shadow: 0 4px 12px rgba(17, 26, 46, 0.12);
}

.ch-comm__ident {
  min-width: 0;
  flex: 1 1 auto;
}

.ch-comm__name {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.2;
  color: #1B365D;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ch-comm__goal {
  margin: 2px 0 0;
  font-size: 14px;
  line-height: 1.35;
  color: rgba(27, 54, 93, 0.78);
}

.ch-comm__goal--none {
  font-style: italic;
}

.ch-comm__goal-set {
  position: relative;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-style: normal;
  font-weight: 600;
  color: #1F4EA8;
  cursor: pointer;
  text-decoration: underline;
}
.ch-comm__goal-set::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 44px;
  transform: translateY(-50%);
}

.ch-comm__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 8px;
}

.ch-comm__actions .ch-tile {
  flex: 0 1 104px;
  min-height: 88px;
  font-size: 14px;
}

.ch-comm__actions .ch-tile--setup {
  flex-basis: 150px;
}

.ch-comm__actions .ch-tile--extras {
  flex: 0 0 auto;
  min-height: 0;
}

.ch-comm__extras {
  display: flex;
  align-items: flex-end;
}

.ch-comm__extras-panel {
  margin: 8px 0 0;
  padding: 8px;
  border-radius: 14px;
  background: rgba(27, 54, 93, 0.05);
  border: 1px solid rgba(27, 54, 93, 0.08);
  box-shadow: inset 0 1px 2px rgba(17, 26, 46, 0.05);
  display: none;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 6px;
}

.ch-comm__extras-panel.is-open {
  display: grid;
  grid-auto-rows: 1fr;
}

.ch-comm__extras-panel > li {
  display: flex;
}

.ch-comm__extras-panel .ch-menu__item {
  height: 100%;
  text-align: center;
  gap: 5px;
}

.ch-comm__extras-panel .md-limited-badge {
  margin-left: 0;
}

.ch-comm__badge {
  margin-top: 2px;
}

.ch-card {
  position: relative;
  overflow: hidden;
  padding: 18px 20px;
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.7) 100%), rgba(27, 54, 93, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.72);
  box-shadow: 0 12px 34px rgba(17, 26, 46, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
}

.ch-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 52%;
  border-radius: inherit;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.45) 0%, rgba(255, 255, 255, 0.1575) 55%, rgba(255, 255, 255, 0) 100%);
  pointer-events: none;
}

.ch-boards__panel {
  padding: 16px;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.42) 48%, rgba(255, 255, 255, 0) 64%), linear-gradient(160deg, #EAEFF6 0%, #D2DAE5 100%);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.95), inset 0 -2px 4px rgba(15, 23, 42, 0.1), 0 3px 8px rgba(27, 54, 93, 0.18);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.42) 48%, rgba(255, 255, 255, 0) 64%), linear-gradient(160deg, #F4F7FB 0%, #E6EBF2 100%);
