#button_settings .btn-group-vertical .btn:hover {
  background: linear-gradient(150deg, #ffffff 0%, rgba(233, 238, 244, 0.96) 50%, rgba(200, 209, 221, 0.92) 100%);
  border-color: rgba(27, 54, 93, 0.24);
  box-shadow: inset 0 1px 0 rgb(255, 255, 255), 0 2px 8px rgba(27, 54, 93, 0.14);
