.la-repairs-wrap .cursor_navigation .btn.la-repairs-btn:focus-visible {
  outline: 3px solid #2A9D8F;
  outline-offset: 2px;
}

.la-big-button-modal-wrap .cursor_navigation .btn[disabled],
