/* Registration confirmation screen (user.confirm_registration). Mirrors the
   .login-card auth treatment — centered, soft dual-radial gradient, teal top
   border, Maitree title — with a success/error status badge and a single Home
   CTA. Lives in the user outlet below the Home/Account/Logs pill-nav. */
.la-reg-confirm {
  display: flex;
  justify-content: center;
  padding: 40px 24px;
}

.la-reg-confirm__card {
  width: 100%;
  max-width: 480px;
  text-align: center;
  background: radial-gradient(ellipse 50% 60% at 15% 20%, rgba(78, 205, 196, 0.07) 0%, transparent 70%), radial-gradient(ellipse 45% 50% at 85% 70%, rgba(58, 107, 199, 0.05) 0%, transparent 70%), rgba(255, 255, 255, 0.95);
  border-radius: 16px;
  padding: 40px 32px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-top: 1px solid rgba(20, 127, 130, 0.14);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06), 0 8px 24px rgba(0, 0, 0, 0.07), 0 24px 48px -12px rgba(0, 0, 0, 0.08);
}

.la-reg-confirm__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.la-reg-confirm__icon--success {
  color: #2A9D8F;
  background: rgba(42, 157, 143, 0.12);
}

.la-reg-confirm__icon--error {
  color: #C0392B;
  background: rgba(192, 57, 43, 0.1);
}

.la-reg-confirm__title {
  font-family: "Maitree", serif;
  font-size: 26px;
  font-weight: normal;
  color: #1b2a4a;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin: 0 0 12px;
}
@media (max-width: 480px) {
  .la-reg-confirm__title {
    font-size: 22px;
  }
}

.la-reg-confirm__message {
  font-family: "Lexend", "Nunito Sans", system-ui, sans-serif;
  font-size: 18px;
  color: #374151;
  line-height: 1.5;
  max-width: 40ch;
  margin: 0 auto 28px;
}

.la-reg-confirm__cta {
  display: inline-flex;
  align-items: center;
}

/* Success celebration: a party-popper badge with confetti bursting from behind
   it. The badge sits centered; the celebrate wrapper owns the bottom spacing
   (the plain --error badge keeps its own auto margin). */
.la-reg-confirm__celebrate {
  position: relative;
  width: 64px;
  height: 64px;
  margin: 0 auto 20px;
}

.la-reg-confirm__celebrate .la-reg-confirm__icon {
  margin: 0;
}

/* Party-popper icon pops in on entry. */
.la-reg-confirm__icon--success svg {
  animation: la-reg-pop 0.5s ease-out both;
}

/* Confetti pieces burst outward on a gentle loop. Each carries its own
   direction (--tx/--ty in px), spin (--rot), color and delay. Pieces are
   pre-centered on the badge's midpoint via negative margins, so the keyframe
   translate stays pure-px (no mixed %+px calc for SassC to choke on). */
.la-reg-confirm__confetti {
  position: absolute;
  top: 50%;
  left: 50%;
  margin: -3.5px 0 0 -3.5px;
  width: 7px;
  height: 7px;
  border-radius: 1px;
  opacity: 0;
  animation: la-reg-confetti 2.6s ease-out infinite;
}

.la-reg-confirm__confetti--a {
  --tx: -40px;
  --ty: -26px;
  --rot: 200deg;
  background: #2A9D8F;
  animation-delay: 0s;
}

.la-reg-confirm__confetti--b {
  --tx: 38px;
  --ty: -32px;
  --rot: -220deg;
  background: #4C86D8;
  animation-delay: 0.12s;
}

.la-reg-confirm__confetti--c {
  --tx: -30px;
  --ty: 30px;
  --rot: 160deg;
  background: #F4A259;
  animation-delay: 0.24s;
}

.la-reg-confirm__confetti--d {
  --tx: 34px;
  --ty: 28px;
  --rot: -160deg;
  background: #E76F92;
  animation-delay: 0.36s;
}

.la-reg-confirm__confetti--e {
  --tx: -6px;
  --ty: -44px;
  --rot: 260deg;
  background: #F6C453;
  animation-delay: 0.5s;
}

.la-reg-confirm__confetti--f {
  --tx: 8px;
  --ty: 42px;
  --rot: -120deg;
  background: #6C5CE7;
  animation-delay: 0.62s;
}

@keyframes la-reg-pop {
  0% {
    transform: scale(0) rotate(-14deg);
  }
  60% {
    transform: scale(1.15) rotate(4deg);
  }
  100% {
    transform: scale(1) rotate(0);
  }
}
@keyframes la-reg-confetti {
  0% {
    transform: translate(0, 0) scale(0.3) rotate(0deg);
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    transform: translate(var(--tx), var(--ty)) scale(1) rotate(var(--rot));
    opacity: 0;
  }
}
/* Respect reduced-motion: no burst or pop; the party-popper badge stays static. */
@media (prefers-reduced-motion: reduce) {
  .la-reg-confirm__icon--success svg {
    animation: none;
  }
  .la-reg-confirm__confetti {
    animation: none;
    opacity: 0;
  }
}
.login-card {
