  max-height: 100px;
}

.md-profiles__meta--indent {
  margin-left: 30px;
}

.md-profiles__priors {
  margin-left: 15px;
  /* #888 was 3.54:1 on white — under AA for this size. Same muted intent, 5.9:1. */
  color: rgba(27, 54, 93, 0.75);
}

.md-profiles__heading {
  margin-top: 0;
}

.md-profiles__current {
  margin: 10px 0 20px;
}

.md-profiles__note {
  margin: 20px 0;
}

.md-profiles__status {
  margin-top: -10px;
  margin-left: 20px;
  font-style: italic;
  color: rgba(27, 54, 93, 0.75);
}

.md-profiles__lookup {
