/* ═══════════════ Organization Settings ═══════════════ */
.md-org-settings-form {
  max-width: 680px;
  margin: 0 auto;
}

.md-org-settings-card {
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(27, 54, 93, 0.08);
  border-radius: 18px;
  padding: 24px;
  margin-bottom: 16px;
}

.md-org-settings-card__title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  font-weight: 800;
  color: var(--md-ink, #111A2E);
  margin: 0 0 20px;
  letter-spacing: -0.01em;
}

.md-org-settings-card__title svg {
  opacity: 0.5;
  flex-shrink: 0;
}

.md-org-settings-card__host-chip {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 8px;
  background: rgba(76, 134, 216, 0.1);
  color: #2860C9; /* WCAG AA fix. */
  font-size: 14px;
  font-weight: 600;
  margin-left: 4px;
}

.md-org-settings-field {
  margin-bottom: 18px;
}

/* bound-select / modern-select use tagName:span; an inline span shrinks
   the hit target so clicks on the painted trigger miss the <button>.
   Same fix as `.md-modal-body .md-modal-field > span`. */
.md-org-settings-field > span {
  display: block;
  width: 100%;
  max-width: 100%;
}

.md-org-settings-field__label {
  display: block;
  font-size: 14px;
  font-weight: 700;
  color: var(--md-navy, #1B365D);
  letter-spacing: 0.01em;
  margin-bottom: 6px;
}

.md-org-settings-field__row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.md-org-settings-field__static {
  font-size: 14px;
  color: var(--md-ink, #111A2E);
}

.md-org-settings-field__suffix {
  font-size: 14px;
  color: var(--md-muted, #1B365D);
  opacity: 0.7;
}

.md-org-settings-field__suffix--pending {
  font-style: italic;
  opacity: 0.5;
}

.md-org-settings-field__hint {
  display: block;
  font-size: 14px;
  color: var(--md-muted, #1B365D);
  opacity: 0.6;
  font-style: italic;
  margin-top: 4px;
  line-height: 1.5;
}

.md-org-settings-field__hint--warn {
  color: #e67e22;
  opacity: 1;
  font-style: normal;
  font-weight: 500;
}

.md-org-settings-field__nested {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
  padding-left: 16px;
  border-left: 3px solid rgba(76, 134, 216, 0.15);
}

.md-org-settings-input {
  display: block;
  width: 100%;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1px solid rgba(27, 54, 93, 0.12);
  background: rgba(255, 255, 255, 0.9);
  font-size: 14px;
  color: var(--md-ink, #111A2E);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.md-org-settings-input:focus-visible {
  outline: none;
  border-color: rgba(76, 134, 216, 0.5);
  box-shadow: 0 0 0 3px rgba(76, 134, 216, 0.12);
  background: #fff;
}

.md-org-settings-input--sm {
  width: auto;
  min-width: 120px;
  max-width: 200px;
  display: inline-block;
}

.md-org-settings-input--xs {
  width: auto;
  min-width: 60px;
  max-width: 90px;
  display: inline-block;
  text-align: center;
}

/* ADMIN ACTIONS (templates/organization/extras.hbs, restyled 2026-10-02 onto the Settings
   primitives above). What those do not already cover: an input that shares its row with a
   button, a two-up grid for the purchase forms, and the lists (blocked emails and cells, custom
   purchases). */
.md-org-admin-actions__input {
  flex: 1 1 220px;
  width: auto;
  min-width: 0;
}

.md-org-admin-actions__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
  margin: 14px 0;
}

.md-org-admin-actions__create {
  margin-top: 20px;
}

.md-org-admin-actions__check {
  margin-bottom: 14px;
}

.md-org-admin-list {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  max-height: 260px;
  overflow: auto;
  border: 1px solid rgba(27, 54, 93, 0.08);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
}

.md-org-admin-list__item {
  padding: 10px 14px;
  font-size: 14px;
  color: var(--md-ink, #111A2E);
  overflow-wrap: anywhere;
}

.md-org-admin-list__item + .md-org-admin-list__item {
  border-top: 1px solid rgba(27, 54, 93, 0.06);
}

.md-org-admin-list--gifts {
  max-height: 420px;
}

.md-org-admin-gift {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.md-org-admin-gift__icon {
  flex: 0 0 auto;
  font-size: 22px;
  line-height: 1;
  color: #2860C9;
  padding-top: 2px;
}

.md-org-admin-gift__body a {
  font-weight: 600;
}

.md-org-admin-gift__meta {
  display: block;
  margin-top: 2px;
  font-size: 14px;
  color: var(--md-muted, #1B365D);
}

/* Billing Details' four license counts: two by two, one column on phones. */
.md-org-billing-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (max-width: 550px) {
  .md-org-billing-grid {
    grid-template-columns: 1fr;
  }
}
/* BILLING DETAILS' "Associated Purchases" (templates/organization/subscription.hbs, restyled
   2026-10-02): user / purchase / expires as rows in the same rounded panel as the lists above,
   with a muted header row. Stacks to one column on narrow screens. */
.md-org-billing-subs {
  border: 1px solid rgba(27, 54, 93, 0.08);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.7);
  overflow: hidden;
}

.md-org-billing-subs__row {
  display: grid;
  grid-template-columns: 1.2fr 1.4fr 1fr;
  gap: 12px;
  align-items: center;
  padding: 10px 14px;
  font-size: 14px;
  color: var(--md-ink, #111A2E);
}

.md-org-billing-subs__row + .md-org-billing-subs__row {
  border-top: 1px solid rgba(27, 54, 93, 0.06);
}

.md-org-billing-subs__row--head {
  font-weight: 700;
  color: var(--md-muted, #1B365D);
  background: rgba(27, 54, 93, 0.03);
}

.md-org-billing-subs__user {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  overflow-wrap: anywhere;
