  overflow-y: auto;
  padding: 48px 24px 56px;
  color: #fff;
  background: radial-gradient(60% 45% at 18% 0%, rgba(54, 125, 142, 0.35), rgba(0, 0, 0, 0) 70%), radial-gradient(55% 40% at 85% 10%, rgba(83, 111, 174, 0.3), rgba(0, 0, 0, 0) 70%);
}

.md-categorize-soon__inner {
  max-width: 1040px;
  margin: 0 auto;
}

.md-categorize-soon__hero {
