  max-width: 100%;
}

/* --- attributions ----------------------------------------------------- */
.la-utterance-attrib__toggle {
  margin: 0;
  font-size: 15px;
}

.la-utterance-attrib__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.la-utterance-attrib__item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(17, 26, 46, 0.08);
  font-size: 15px;
}

.la-utterance-attrib__item:last-child {
  border-bottom: 0;
}

.la-utterance-attrib__item--sound {
  flex-wrap: wrap;
}

.la-utterance-attrib__thumb {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex-shrink: 0;
}

.la-utterance-attrib__sound-label {
