  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 12px;
  font-size: 18px;
}

.la-inbox__msg-avatar {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  flex-shrink: 0;
  order: 2;
  margin-left: auto;
  object-fit: cover;
}

.la-inbox__msg-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.la-inbox__row-clear {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
}

.la-inbox-modal-footer {
  /* Re-supplied from `.md-modal-footer` (:89779), which this no longer uses --
     that rule was the only thing laying the footer out. */
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-top: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.6);
  flex-shrink: 0;
}

.la-inbox__working {
  flex: 1 1 100%;
  margin-bottom: 5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--md-muted);
  font-size: 18px;
  text-align: left;
